// Decoders for the compressed exact tables generated by tools/conv/trig.py.
// Every function returns the upstream table value bit for bit.

#ifndef DMC_TRIG_H
#define DMC_TRIG_H

#include <stdint.h>

#include "trig_tables.h"

#define DMC_DETAIL_HIGH 0
#define DMC_DETAIL_LOW 1

int dmc_finesine(unsigned i);       // finesine[i], i < 10240
int dmc_finecosine(unsigned i);     // finecosine[i] = finesine[i + 2048], i < 8192
int dmc_finetangent(unsigned i);    // i < 4096
uint32_t dmc_tantoangle(unsigned i);  // i <= 2048

// View tables for the 320x200 view, detail 0 (320 columns) or 1 (160 columns)
int dmc_viewangletox(int detail, unsigned i);    // i < 4096, fencepost cases removed
uint32_t dmc_xtoviewangle(int detail, unsigned x);  // x <= viewwidth
int dmc_yslope(unsigned y);         // y < 200, same for both detail modes

// Colormap row (0-31) of the vanilla scalelight and zlight tables
int dmc_scalelight(unsigned lightnum, unsigned scale);  // lightnum < 16, scale < 48
int dmc_zlight(unsigned lightnum, unsigned z);          // lightnum < 16, z < 128
int dmc_light_startmap(unsigned lightnum);

// COLORMAP rows 0-32 (32 = invulnerability)
const uint8_t *dmc_colormap_row(unsigned row);

// Decoder calls by kind, counted in host builds with DMC_RSTATS
// (tests/render/rstats.py turns them into time per frame): finesine and
// finecosine, the inline finetangent of the wall columns and tantoangle.
enum { DMC_TRIG_SINE, DMC_TRIG_TANGENT, DMC_TRIG_ATAN, DMC_TRIG_KINDS };
#ifdef DMC_RSTATS
extern uint32_t dmc_trig_calls[DMC_TRIG_KINDS];
#define DMC_TRIG_COUNT(k) (dmc_trig_calls[k]++)
#else
#define DMC_TRIG_COUNT(k) ((void)0)
#endif

// finetangent[i] for i < 4096 without a call, for the per-column path
// of the renderer. dmc_finetangent is this function out of line.
static inline __attribute__((always_inline)) int dmc_finetangent_inline(unsigned i)
{
    unsigned k = i < 2048u ? i : 4095u - i;
    int v;
    DMC_TRIG_COUNT(DMC_TRIG_TANGENT);
    if (k < DMC_TAN_FULL) {
        v = dmc_tan_full[k];
    } else {
        k -= DMC_TAN_FULL;
        const int32_t *c = &dmc_tan_coarse[k >> 3];
        int f = (int)(k & 7u);
        int d1 = c[1] - c[0], d2 = c[2] - 2 * c[1] + c[0];
        // the signed residual nibble of entry k
        int r = (int32_t)((uint32_t)dmc_tan_resid[k >> 1] << (28u - 4u * (k & 1u))) >> 28;
        v = c[0] + ((d1 * f) >> 3) + ((d2 * f * (f - 8)) >> 7) + r;
    }
    return i < 2048u ? v : -v;
}

#endif
